return {["scripts/actions/abilities/coursers_roll.lua"]={["Path"]="scripts/actions/abilities/coursers_roll.lua",["SHA256"]="d9a9073a5b75aa3fdb29dfeb2077b4078e874ce5fe44368eebd8bb82cb01f5b3",["Text"]="-----------------------------------\n-- Ability: Courser's Roll\n-- Enhances \"Snapshot\" effect for party members within area of effect.\n-- Optimal Job: None\n-- Lucky Number: 3\n-- Unlucky Number: 9\n-- Level: 81\n-- Phantom Roll +1 Value: 1\n--\n-- No Reliable Community Data available. Numbers Based on Blitzer's Roll Values.\n--\n-- Die Roll    | Snapshot+\n-- --------    -------\n-- 1           |+2\n-- 2           |+3\n-- 3           |+11\n-- 4           |+4\n-- 5           |+5\n-- 6           |+6\n-- 7           |+7\n-- 8           |+8\n-- 9           |+1\n-- 10          |+10\n-- 11          |+12\n-- Bust        |-5\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/cover.lua"]={["Path"]="scripts/actions/abilities/cover.lua",["SHA256"]="8178ea6345b79f4b1e72be5c59b583d635f1387a3ce76bfbc2980bd63c70b593",["Text"]="-----------------------------------\n-- Ability: Cover\n-- Allows you to protect party members by placing yourself between them and the enemy.\n-- Obtained: Paladin Level 35\n-- Recast Time: 0:03:00\n-- Duration: 0:00:15 - 0:00:35\n-- Info from https://www.bg-wiki.com/bg/Cover\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.paladin.checkCover(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.paladin.useCover(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/crooked_cards.lua"]={["Path"]="scripts/actions/abilities/crooked_cards.lua",["SHA256"]="71cfe1906d147401afb8c7fc0f4bca4cd8450ba3e35cf799f021907165212f31",["Text"]="-----------------------------------\n-- Ability: Crooked Cards\n-- Description: Increases the effects of the next phantom roll.\n-- Obtained: COR Level 95\n-- Recast Time: 0:10:00\n-- Duration: 0:01:00(or the next roll used)\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    target:addStatusEffect(xi.effect.CROOKED_CARDS, { power = 20, duration = 60, origin = player })\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/curing_waltz.lua"]={["Path"]="scripts/actions/abilities/curing_waltz.lua",["SHA256"]="e78952bff2ff1f338c1d1a3a23a0938559e65ddcb9f61198291772e557ea845e",["Text"]="-----------------------------------\n-- Ability: Curing Waltz\n-- Heals HP to target player.\n-- Obtained: Dancer Level 15\n-- TP Required: 20%\n-- Recast Time: 00:06\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dancer.checkWaltzAbility(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dancer.useWaltzAbility(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/curing_waltz_ii.lua"]={["Path"]="scripts/actions/abilities/curing_waltz_ii.lua",["SHA256"]="5e9803095a916560b08e4b1b65c17e97c2415a6ebd5e2f9617bc9497860cd118",["Text"]="-----------------------------------\n-- Ability: Curing Waltz II\n-- Heals HP to target player.\n-- Obtained: Dancer Level 30\n-- TP Required: 3