lityObject\n"},["scripts/actions/abilities/curing_waltz_v.lua"]={["Path"]="scripts/actions/abilities/curing_waltz_v.lua",["SHA256"]="e66c764ff0a2cbb6473d3db0e421d2370b563264cf0c35ff7c8c5b1a9df207a3",["Text"]="-----------------------------------\n-- Ability: Curing Waltz V\n-- Restores target's HP\n-- Obtained: Dancer Level 87\n-- TP Required: 80%\n-- Recast Time: 00:23\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dancer.checkWaltzAbility(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dancer.useWaltzAbility(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/cutting_cards.lua"]={["Path"]="scripts/actions/abilities/cutting_cards.lua",["SHA256"]="b9396c191966fd0f5723e861879ed54742a727041362c00f2c746491428bd26e",["Text"]="-----------------------------------\n-- Ability: Cutting Cards\n-- Description: Reduces the recast times of other party members' special abilities. The degree to which they are reduced is determined by the number rolled.\n-- Obtained: COR Level 96\n-- Recast Time: 01:00:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    ability:setRecast(math.max(0, ability:getRecast() - player:getMod(xi.mod.ONE_HOUR_RECAST) * 60))\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    xi.job_utils.corsair.useCuttingCards(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/dancers_roll.lua"]={["Path"]="scripts/actions/abilities/dancers_roll.lua",["SHA256"]="5a66127812448d6f79776b6ae2e142f85d135e4c98783ba2101b860dc6940b98",["Text"]="-----------------------------------\n-- Ability: Dancer's Roll\n-- Grants Regen status to party members within area of effect\n-- Optimal Job: Dancer\n-- Lucky Number: 3\n-- Unlucky Number: 7\n-- Level: 61\n-- Phantom Roll +1 Value: 2\n--\n-- Die Roll    |No DNC              |With DNC\n-- --------    ----------           ----------\n-- 1           |3HP/Tick            |7HP/Tick\n-- 2           |4HP/Tick            |8HP/Tick\n-- 3           |12HP/Tick           |16HP/Tick\n-- 4           |5HP/Tick            |9HP/Tick\n-- 5           |6HP/Tick            |10HP/Tick\n-- 6           |7HP/Tick            |11HP/Tick\n-- 7           |1HP/Tick            |5HP/Tick\n-- 8           |8HP/Tick            |12HP/Tick\n-- 9           |9HP/Tick            |13HP/Tick\n-- 10          |10HP/Tick           |14HP/Tick\n-- 11          |16HP/Tick           |20HP/Tick\n-- 12+         |-4hp(regen)/Tick    |-4hp(regen)/Tick\n-- A bust will cause a regen effect on you to be reduced by 4, it will not drain HP from you if no regen effect is active.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/dark_arts.lua"]={["Path"]="scripts/actions/abilities/dark_arts.lua",["SHA256"]="59fb34a961ea7e57993fa4a013563f78a706daedabb74d05c10ceeecc6b2d22d",["Text"]="-----------------------------------\n-- Ability: Dark Arts\n-- Optimizes black magic capability while lowering white magic proficiency. Grants a bonus to enfeebling, elemental, and dark magic. Also grants access to Stratagems.\n-- Obtained: Scholar Level 10\n-- Recast Time: 1:00\n-- Duration: 2:00:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if\n        player:hasStatusEffect(xi.effect.DARK_ARTS) or\n        player:hasStatusEffect(xi.effect.ADDENDUM_BLACK)\n    then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:delStatusEffectSilent(xi.effect.LIGHT_ARTS)\n    player:delStatusEffect(xi.effect.ADDENDUM_WHITE)\n    player:delStatusEffect(xi.effect.PENURY)\n    player:delStatusEffect(xi.effect.CELERITY)\n    player:delStatusEffect(xi.effect.ACCESSION)\n    player:delStatusEffect(xi.effect.RAPTURE)\n    player:delStatusEffect(xi.effect.ALTRUISM)\n    player:delStatusEffect(xi.effect.TRANQUILITY)\n    player:delStatusEffect(xi.effect.PERPETUANCE)\n\n    local helixbonus = 0\n\n    if player:getMainJob() == xi.job.SCH and player:getMainLvl() >= 20 then\n        helixbonus = math.floor(player:getMainLvl() / 4)\n    end\n\n    player:addStatusEffect(xi.effect.DARK_ARTS, { power = 1, duration = 7200, origin = player, subPower = helixbonus })\n\n    return xi.effect.DARK_ARTS\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/dark_maneuver.lua"]={["Path"]="scripts/actions/abilities/dark_maneuver.lua",["SHA256"]="62a7f4e1d053131a85678d85a605a723026c924d2efe9143b9448cc95ad7c5f1",["Text"]="-----------------------------------\n-- Ability: Dark Maneuver\n-- Enhances the effect of dark attachments. Must have animator equipped.\n-- Obtained: Puppetmaster level 1\n-- Recast Time: 10 seconds (shared with all maneuvers)\n-- Duration: 1 minute\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.automaton.onManeuverCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.automaton.onUseManeuver(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/dark_seal.lua"]={["Path"]="scripts/actions/abilities/dark_seal.lua",["SHA256"]="994f09467be338b18e2aee76557b945eff9bfd2ed2e30338ff38b31951e52913",["Text"]="-----------------------------------\n-- Ability: Dark Seal\n-- Description: Enhances the accuracy of your next dark magic spell.\n-- Obtained: Dark Knight Level 75\n-- Recast Time: 00:05:00\n-- Duration: 1 Spell or 60 seconds, whichever occurs first.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dark_knight.useDarkSeal(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/dark_shot.lua"]={["Path"]="scripts/actions/abilities/dark_shot.lua",["SHA256"]="7f393e5951c253eca03e73cc3173166e9ecc8f0775c8d9fba19629c11c18d23a",["Text"]="-----------------------------------\n-- Ability: Dark Shot\n-- Consumes a Dark Card to enhance dark-based debuffs. Additional effect: Dark-based Dispel\n-- Bio Effect: Attack Down Effect +5% and DoT + 3\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.checkQuickDraw(player, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.corsair.useElementalShot(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/deactivate.lua"]={["Path"]="scripts/actions/abilities/deactivate.lua",["SHA256"]="2530dc8bf22f612ab417dcaaa1e69d6bb3d45ca75ec21d45a5a22938a1d46202",["Text"]="-----------------------------------\n-- Ability: Deactivate\n-- Deactivates your automaton.\n-- Obtained: Puppetmaster Level 1\n-- Recast Time: 1:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityCheckDeactivate(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityUseDeactivate(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/decoy_shot.lua"]={["Path"]="scripts/actions/abilities/decoy_shot.lua",["SHA256"]="053510f4bfb63909dbeb0b33e2f5e98fa1ecc1a46ba30ce0cb478b0bf98eae5a",["Text"]="-----------------------------------\n-- Ability: Decoy Shot\n-- Description: Diverts enmity when launching a ranged attack from behind a party member.\n-- Obtained: RNG Level 95\n-- Recast Time: 00:05:00\n-- Duration: 00:03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.ranger.checkDecoyShot(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.ranger.useDecoyShot(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/deep_breathing.lua"]={["Path"]="scripts/actions/abilities/deep_breathing.lua",["SHA256"]="7f9a7dea5068eb5d699914ee911bbbe6d3a4462a7f5afc9e8dadafd45b3abaf0",["Text"]="-----------------------------------\n-- Ability: Deep Breathing\n-- Enhances the effect of next breath used by wyvern.\n-- Obtained: Dragoon Level 75\n-- Recast Time: 5 minutes\n-- Duration: 0:03:00 or until the next breath is executed\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dragoon.abilityCheckDeepBreathing(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dragoon.useDeepBreathing(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/defender.lua"]={["Path"]="scripts/actions/abilities/defender.lua",["SHA256"]="47a61a0dc53afa1532d438e5fda7890debfeaf15494b7e7dd35ef317d38ee7b7",["Text"]="-----------------------------------\n-- Ability: Defender\n-- Job: Warrior\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.warrior.useDefender(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/dematerialize.lua"]={["Path"]="scripts/actions/abilities/dematerialize.lua",["SHA256"]="e206c5584b161e787a39fc667ee8caa07f2c53d9f1f3fec871375f6546ed5898",["Text"]="-----------------------------------\n-- Ability: Dematerialize\n-- Enhances the effects of your luopan.\n-- Prevents your luopan from receiving damage.\n-- Obtained: Geomancer Level 70\n-- Recast Time: 00:10:00\n-- Duration: 00:01:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.geomancer.geoOnAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.geomancer.dematerialize(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/deploy.lua"]={["Path"]="scripts/actions/abilities/deploy.lua",["SHA256"]="65a6bc5ccf92cd72f4656baf91777977ac437bc8c5670e81ed6fc6e944dc3d89",["Text"]="-----------------------------------\n-- Ability: Deploy\n-- Orders your automaton to attack.\n-- Obtained: Puppetmaster Level 1\n-- Recast Time: 10 seconds\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbility