2a73c0a817934d0da1f98a2a387ccd6b300d42aafd50b31a14f0",["Text"]="-----------------------------------\n-- Ability: Deus Ex Automata\n-- Calls forth your automaton in an unsound state.\n-- Obtained: Puppetmaster Level 5\n-- Recast Time: 1:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityCheckDeusExAutomata(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityUseDeusExAutomata(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/devotion.lua"]={["Path"]="scripts/actions/abilities/devotion.lua",["SHA256"]="a1866486ab827b833b64981a2527c323a5a437a8f3f6c38b4159f6814908721b",["Text"]="-----------------------------------\n-- Ability: Devotion\n-- Sacrifices HP to grant a party member the same amount in MP.\n-- Obtained: White Mage Level 75\n-- Recast Time: 0:10:00\n-- Duration: Instant\n-- Target: Party member, cannot target self.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.white_mage.checkDevotion(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.white_mage.useDevotion(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/diabolic_eye.lua"]={["Path"]="scripts/actions/abilities/diabolic_eye.lua",["SHA256"]="542b6c933f7565539827934fbf31184b5041bfb3eface8c581112fa70b7a4f28",["Text"]="-----------------------------------\n-- Ability: Diabolic Eye\n-- Description: Reduces max. HP, increases accuracy.\n-- Obtained: Dark Knight Level 75\n-- Recast Time: 00:05:00\n-- Duration: 00:03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dark_knight.useDiabolicEye(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/diffusion.lua"]={["Path"]="scripts/actions/abilities/diffusion.lua",["SHA256"]="49a00538b415de83fb927b7ed96fb35f534eb3f4d35e3cd2c5749f1430f41a1e",["Text"]="-----------------------------------\n-- Ability: Diffusion\n-- Grants the effect of your next support Blue Magic spell to party members within range.\n-- Obtained: Blue Mage Level 75\n-- Recast Time: 10:00\n-- Duration: 1:00, or until the next blue magic spell is cast.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    xi.job_utils.blue_mage.checkDiffusion(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.blue_mage.useDiffusion(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/dismiss.lua"]={["Path"]="scripts/actions/abilities/dismiss.lua",["SHA256"]="0223b7fd9c840a7c08ac10d09d90151521fc0797056270ba35353ce3679adb26",["Text"]="-----------------------------------\n-- Ability: Dismiss\n-- Sends the Wyvern away.\n-- Obtained: Dragoon Level 1\n-- Recast Time: 5.00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    -- You can't actually use dismiss on retail unless your wyvern is up\n    -- This is on the pet menu, but just in case...\n    return xi.job_utils.dragoon.abilityCheckRequiresPet(player, target, ability, false)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    -- Reset the Call Wyvern Ability.\n    local pet = player:getPet()\n\n    if\n        pet and\n        pet:getHP() == pet:getMaxHP()\n    then\n        player:resetRecast(xi.recast.ABILITY, 163) -- call_wyvern\n    end\n\n    target:despawnPet()\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/divine_caress.lua"]={["Path"]="scripts/actions/abilities/divine_caress.lua",["SHA256"]="9cf4858be3ac49e08bf4661f86e8bf46d4badd2f3cd5fdaf1aeeb17a5469ae68",["Text"]="-----------------------------------\n-- Ability: Divine Caress\n-- Description: If the next spell you cast cures a status ailment, your target will gain enhanced resistance to that ailment.\n-- Obtained: WHM Level 83\n-- Recast Time: 00:01:00\n-- Duration: 0:01:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.white_mage.useDivineCaress(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/divine_emblem.lua"]={["Path"]="scripts/actions/abilities/divine_emblem.lua",["SHA256"]="9a4dbd3c44bd1ec791e584b40c0ac206abba925deb510d72d9ad2ec719034832",["Text"]="-----------------------------------\n-- Ability: Divine Emblem\n-- Description: Enhances the accuracy of your next divine magic spell and increases enmity.\n-- Obtained: PLD Level 78\n-- Recast Time: 00:03:00\n-- Duration: 00:01:00 or the next spell cast\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.paladin.useDivineEmblem(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/divine_seal.lua"]={["Path"]="scripts/actions/abilities/divine_seal.lua",["SHA256"]="d1174f17b2165faeaa991de66c411cee55e1a7c628e06a7b7e4e7e12d5d80f05",["Text"]="-----------------------------------\n-- Ability: Divine Seal\n-- Enhances the potency of the user's next healing spell.\n-- Obtained: White Mage Level 15\n-- Recast Time: 10:00\n-- Duration: 1 Spell or 60 seconds, whichever occurs first.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.white_mage.useDivineSeal(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/divine_waltz.lua"]={["Path"]="scripts/actions/abilities/divine_waltz.lua",["SHA256"]="1de4df46a1f7db4fd46f92e9e2fdfe01258ec4d9185a3fe61669da3d2e5ad24b",["Text"]="-----------------------------------\n-- Ability: Divine Waltz\n-- Heals party members within area of effect.\n-- Obtained: Dancer Level 25\n-- TP Required: 40%\n-- Recast Time: 00:13\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dancer.checkWaltzAbility(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dancer.useWaltzAbility(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/divine_waltz_ii.lua"]={["Path"]="scripts/actions/abilities/divine_waltz_ii.lua",["SHA256"]="f8dfac1225c61d9d0b96bba8211952327e56050fa9299495b71773f98cff5f2f",["Text"]="-----------------------------------\n-- Ability: Divine Waltz II\n-- Restores the HP of all party members within a small radius.\n-- Obtained: Dancer Level 78\n-- TP Required: 80%\n-- Recast Time: 00:20\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dancer.checkWaltzAbility(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dancer.useWaltzAbility(player, target, ability, action)\nend\n\nreturn abilityObject\n"}};
